def add(src,sec,title,req,systems,kind='normative'):
    sid=re.sub(r'[^a-z0-9]+','-',src.lower()).strip('-'); ss=re.sub(r'[^a-z0-9]+','-',sec.lower()).strip('-')
    R.append({'id':f'{src}:{sec}','anchor':f'{sid}-{ss}','source_id':src,'section':sec,'title':title,'requirement_paraphrase':req,'classification':kind,'systems':list(systems) if not isinstance(systems,str) else [systems],'implementation_status':'unmapped','implementation_refs':[],'test_refs':[],'test_evidence_status':'no_named_repository_test','independent_verification_status':'none','independent_verification_note':'No independent oracle or system-level evaluation is recorded for this clause.','official_example_fixture':None,'legacy_rule_ids':[],'closure_action':'Inspect this exact official clause against the selected engine; add a named code mapping and clause-specific test, or record why it is caller-owned/out of scope.'})
def group(src,systems,rows,kind='normative'):
    for row in rows:add(src,*row,systems,kind)
def link(src,sec,status,impl=(),tests=(),independent='none',fixture=None,legacy=(),note=None,close=None):
    matches=[x for x in R if x['source_id']==src and x['section']==sec]
    if not matches: raise RuntimeError(f'no record for {src} / {sec}; available={[x["section"] for x in R if x["source_id"]==src]}')
    r=matches[0]
    r['implementation_status']=status;r['implementation_refs']=list(impl);r['test_refs']=list(tests)
    r['test_evidence_status']='linked_repository_tests' if tests else 'no_named_repository_test'
    r['independent_verification_status']=independent or 'none';r['official_example_fixture']=fixture;r['legacy_rule_ids']=list(legacy)
    r['independent_verification_note']=note or ('Source-authored worked-example regression only; not a full-system or independent conformance result.' if fixture else ('Repository test evidence only; not an independent evaluation.' if tests else 'No independent oracle or system-level evaluation is recorded for this clause.'))
    if close:r['closure_action']=close
    elif status=='implemented':r['closure_action']='Keep the mapping current; add independent per-system evidence before any conformity statement.'
    elif status=='partial':r['closure_action']='Resolve the documented partial coverage/strategy and add clause-specific independent evidence; do not infer full conformity.'
    elif status=='caller_supplied':r['closure_action']='Keep the caller-owned input/provenance obligation explicit and validate it in the consuming application.'
    elif status=='out_of_scope':r['closure_action']='No Pairing-Core implementation action; preserve the pairing-only boundary and assign this duty to the caller/THP/arbiter.'
    elif status=='disputed':r['closure_action']='Resolve the reading against the official edition, record an interpretation decision, and add a discriminating regression.'
    elif status=='historical_compat':r['closure_action']='Preserve frozen compatibility behavior; do not describe this edition as the current FIDE rules.'
    elif status=='withdrawn':r['closure_action']='Keep withdrawn absent an authoritative clause; do not revive by inference.'

